// Interactive skeleton for CF1375F (Integer Game).
// This implementation uses an AP-based heuristic to generate moves.

static inline long long compute_first_move(const array<long long,3>& p){
    long long best = -1;
    for (int i = 0; i < 3; ++i) {
        int j = (i + 1) % 3;
        int k = (i + 2) % 3;
        long long y = 2 * p[j] - p[i] - p[k];
        if (y > 0) best = max(best, y);
    }
    if (best < 0) best = 1; // fallback
    return best;
}
static inline long long compute_next_move(const array<long long,3>& p, int /*last_pile*/){
    // Heuristic: reuse the same AP-based candidate generation for the next move.
    long long best = -1;
    for (int i = 0; i < 3; ++i) {
        int j = (i + 1) % 3;
        int k = (i + 2) % 3;
        long long y = 2 * p[j] - p[i] - p[k];
        if (y > 0) best = max(best, y);
    }
    if (best < 0) best = 1; // fallback
    return best;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a,b,c;
    if(!(cin >> a >> b >> c)) return 0;
    array<long long,3> piles = {a,b,c};

